@Provides
public class HandleHelper extends JavacAnnotationHandler<Helper> {
	private List<JCStatement> getStatementsFromJcNode(JCTree tree) {
		if (tree instanceof JCBlock) return ((JCBlock) tree).stats;
		if (tree instanceof JCCase) return ((JCCase) tree).stats;
		return null;
	}

	private void setStatementsOfJcNode(JCTree tree, List<JCStatement> statements) {
		if (tree instanceof JCBlock) ((JCBlock) tree).stats = statements;
		else if (tree instanceof JCCase) ((JCCase) tree).stats = statements;
		else throw new IllegalArgumentException("Can't set statements on node type: " + tree.getClass());
	}


	private static final HandleHelper SHARED_HELPER = new HandleHelper();
	private static final String GETTER_NODE_NOT_SUPPORTED_ERR = "@Getter is only supported on a class, an enum, or a field.";
	private static final String SETTER_NODE_NOT_SUPPORTED_ERR = "@Setter is only supported on a class or a field.";

	static HandleHelper sharedHelper() {
		return SHARED_HELPER;
	}

	private final java.util.List<String> helperKnownMethodNames = new ArrayList<String>();
	private boolean helperWasUsed;
	private Name helperLocalName;
	private List<JCStatement> helperOriginalStatements;
	private int helperUseCount;

	private JCTree generatedByTree;
	private JavacNode generatedBySource;
	private boolean generatedByNetbeansEditor;
	private int generatedByUseCount;

